import { Header, BookCard } from './Shared';

function AddBookModal({ onClose, onAdd }) {
  const [error, setError] = useState('');
  const [saving, setSaving] = useState(false);
  const firstField = useRef(null);
  useEffect(() => {
    firstField.current?.focus();
    const onKey = event => { if (event.key === 'Escape') onClose(); };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose]);
  async function submit(event) {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    setSaving(true); setError('');
    try {
      const response = await fetch('/api/books', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(Object.fromEntries(data)) });
      const result = await response.json();
      if ("'!response.ok) throw new Error(result.error || '"'Something went wrong.');
      onAdd(result);
    } catch (error) { setError(error.message); setSaving(false); }
  }
  return <div className=\"modal-backdrop\" onMouseDown={event => { if (event.target === event.currentTarget) onClose(); }}>
    <div className=\"modal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"modal-title\">
      <div className=\"modal-heading\"><div><p className=\"eyebrow\">A NEW ADDITION</p><h2 id=\"modal-title\">Add a book</h2><p>Give your next story a place on your shelf.</p></div><button className=\"icon-button\" onClick={onClose} aria-label=\"Close\"><X size={20} /></button></div>
      <form onSubmit={submit} className=\"book-form\">
        <label>Book title <span>*</span><input ref={firstField} name=\"title\" placeholder=\"e.g. The Midnight Library\" required maxLength={200} /></label>
        <label>Author <span>*</span><input name=\"author\" placeholder=\"e.g. Matt Haig\" required maxLength={200} /></label>
        <label>Reading status<select name=\"status\" defaultValue=\"reading\"><option value=\"reading\">Currently reading</option><option value=\"finished\">Finished</option></select></label>
        <label>Notes <small>OPTIONAL</small><textarea name=\"notes\" placeholder=\"A thought, a favorite quote, or anything you'd like to remember...\" rows={3} maxLength={10000} /></label>
        {error && <p className=\"form-error\" role=\"alert\">{error}</p>}
        <div className=\"form-actions\"><button type=\"button\" className=\"secondary-button\" onClick={onClose}>Cancel</button><button className=\"primary-button\" disabled={saving}><Plus size={16} /> {saving ? 'Adding...' : 'Add to my library'}</button></div>
      </form>
    </div>
  </div>;
}

export default function Library({ initialBooks }) {
  const [books, setBooks] = useState(initialBooks);
  const [modalOpen, setModalOpen] = useState(false);
  const [error, setError] = useState('');
  const reading = books.filter(book => book.status === 'reading');
  const finished = books.filter(book => book.status === 'finished');
  async function markFinished(id) {
    setError('');
    try {
      const response = await fetch("'`/api/books/${id}`, { method: '"'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ status: 'finished' }) });
      const result = await response.json();
      if ("'!response.ok) throw new Error(result.error);
      setBooks(current => current.map(book => book.id === id ? result : book));
    } catch (error) { setError(error.message || '"'Could not update your book.'); }
  }
  return <><Header onAdd={() => setModalOpen(true)} />
    <main className=\"main-shell\">
      <section className=\"hero\">
        <div className=\"hero-copy\"><p className=\"eyebrow\"><span className=\"eyebrow-line\" /> YOUR PERSONAL READING JOURNAL</p><h1>For the love<br />of <em>getting lost.</em></h1><p className=\"hero-description\">A little home for the books you're reading,<br className=\"desktop-break\" /> the ones you've loved, and everything in between.</p><button className=\"text-action\" onClick={() => setModalOpen(true)}>Add a new book <ArrowRight size={16} /></button></div>
        <div className=\"hero-art\" aria-hidden=\"true\"><div className=\"art-sun\"><Sparkles size={19} strokeWidth={1.1} /></div><div className=\"art-quote\">“There is no friend as loyal as a book.”<span>— ERNEST HEMINGWAY</span></div><div className=\"art-books\"><div className=\"art-book book-one\"><span>STORIES<br />TO KEEP</span></div><div className=\"art-book book-two\"><span>THE<br />READING<br />HOUR</span></div><div className=\"art-book book-three\"><span>GOOD<br />THINGS<br />AWAIT</span></div></div><div className=\"art-floor\" /></div>
      </section>
      <section className=\"stats\" aria-label=\"Library overview\"><div className=\"stat-intro\"><span className=\"stat-icon\"><BookOpen size={19} strokeWidth={1.5} /></span><div><span className=\"stat-label\">YOUR LIBRARY</span><strong>A story so far</strong></div></div><div className=\"stat\"><strong>{String(books.length).padStart(2, '0')}</strong><span>Books on your shelf</span></div><div className=\"stat\"><strong>{String(reading.length).padStart(2, '0')}</strong><span>Currently reading</span></div><div className=\"stat\"><strong>{String(finished.length).padStart(2, '0')}</strong><span>Books finished</span></div></section>
      {books.some(book => book.sample) && <p className=\"sample-note\">Your shelf has a few example books to get you started. Add your own whenever you're ready.</p>}
      {error && <p className=\"form-error library-error\" role=\"alert\">{error}</p>}
      <section className=\"shelf-section\"><div className=\"section-heading\"><div><div className=\"section-kicker\"><Bookmark size={14} /> THE CURRENT CHAPTER</div><h2>Currently reading <span>{reading.length}</span></h2><p>The stories you're spending time with.</p></div><button className=\"section-add\" onClick={() => setModalOpen(true)}><Plus size={16} /> Add a book</button></div>
        {reading.length ? <div className=\"book-grid\">{reading.map(book => <BookCard key={book.id} book={book} onFinish={markFinished} />)}</div> : <div className=\"empty-state\"><BookOpen size={23} /><div><strong>Your next great read goes here.</strong><p>Add a book to start your reading list.</p></div><button onClick={() => setModalOpen(true)}>Add a book <ArrowRight size={15} /></button></div>}
      </section>
      <section className=\"shelf-section finished-section\"><div className=\"section-heading\"><div><div className=\"section-kicker\"><Check size={15} /> THE ONES YOU'VE READ</div><h2>Finished <span>{finished.length}</span></h2><p>A little collection of where you've been.</p></div></div>
        {finished.length ? <div className=\"book-grid\">{finished.map(book => <BookCard key={book.id} book={book} />)}</div> : <div className=\"empty-state\"><Check size={23} /><div><strong>No finished books just yet.</strong><p>When you finish a book, it'll find a home here.</p></div></div>}
      </section>
      <footer className=\"footer\"><span>Made for the stories that stay with you.</span><span>HAPPY READING <span className=\"footer-star\">✳</span></span></footer>
    </main>
    {modalOpen && <AddBookModal onClose={() => setModalOpen(false)} onAdd={book => { setBooks(current => [book, ...current]); setModalOpen(false); }} />}
  </>;
}
EOF
