;gap:17px;box-shadow:0 4px 18px rgba(55,72,51,.025);transition:box-shadow .2s,transform .2s}.book-card:hover{box-shadow:0 8px 24px rgba(55,72,51,.08);transform:translateY(-2px)}.card-cover-link{flex:none}.cover{height:148px;width:100px;overflow:hidden;border-radius:2px;background:#d6dfd1;box-shadow:3px 5px 9px rgba(41,47,38,.13)}.cover img{display:block;width:100%;height:100%;object-fit:cover}.cover-fallback{height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:10px;padding:10px;color:#fff8e9;border:4px double #ffffff55;font-family:var(--serif);font-size:14px;line-height:1.1}.cover-fallback small{font-family:var(--sans);font-size:8px;line-height:1.2;opacity:.8}.cover-sage{background:#7b9177}.cover-rust{background:#b67d65}.cover-blue{background:#6d8791}.cover-ochre{background:#bf9a62}.cover-plum{background:#8e7d85}.book-card-body{display:flex;flex-direction:column;min-width:0;align-items:flex-start;padding:4px 0 2px}.status{display:inline-flex;align-items:center;gap:6px;font-size:9px;font-weight:700;letter-spacing:.8px;color:#819b7b}.status span{width:6px;height:6px;border-radius:50%;background:#a1b79a}.status-finished{color:#ba9b78}.status-finished span{background:#cbb093}.book-title{font-family:var(--serif);font-size:18px;line-height:1.18;margin-top:14px;letter-spacing:-.2px}.book-title:hover{color:#69826b}.book-author{font-size:11px;color:#9ba096;margin:7px 0 0}.card-bottom{margin-top:auto;padding-top:12px}.finish-link,.view-link{display:inline-flex;align-items:center;gap:6px;border:0;padding:0;background:transparent;color:#779077;font-size:10px;font-weight:700}.check-circle{display:inline-grid;place-items:center;width:15px;height:15px;border:1px solid #b9c9b4;border-radius:50%;font-size:10px}.finished-section{padding-top:42px}.footer{display:flex;justify-content:space-between;margin-top:55px;padding:24px 0 30px;border-top:1px solid #e7ebe3;color:#a5aaa0;font-size:10px}.footer span:last-child{font-size:9px;letter-spacing:1.1px;font-weight:700}.footer-star{color:#92aa8d;font-size:14px"'!important;margin-left:7px}.empty-state{border:1px dashed #dce4d8;background:#fbfcf9;border-radius:6px;min-height:120px;padding:24px;display:flex;align-items:center;gap:18px;color:#8ba088}.empty-state strong{font-family:var(--serif);font-size:18px;color:#536052;font-weight:400}.empty-state p{margin:6px 0 0;color:#999f94;font-size:12px}.empty-state button{margin-left:auto;background:none;border:0;display:flex;align-items:center;gap:8px;color:#718b70;font-size:11px;font-weight:700}.library-error{margin-top:20px}.modal-backdrop{position:fixed;inset:0;z-index:10;background:rgba(35,45,36,.45);display:flex;justify-content:center;align-items:center;padding:20px}.modal{width:min(100%,510px);max-height:calc(100vh - 40px);overflow:auto;background:#fff;border-radius:9px;padding:32px;box-shadow:0 22px 80px #25342633}.modal-heading{display:flex;justify-content:space-between;align-items:flex-start}.modal-heading .eyebrow{margin-bottom:10px}.modal-heading h2{font-family:var(--serif);font-weight:400;font-size:31px;margin:0}.modal-heading p:not(.eyebrow){color:#92998f;font-size:12px;margin:8px 0 22px}.icon-button{border:0;background:#f3f5f0;border-radius:50%;width:34px;height:34px;display:grid;place-items:center;color:#718170}.book-form{display:grid;gap:16px}.book-form label{display:flex;flex-direction:column;gap:8px;font-size:12px;font-weight:700;color:#59665a}.book-form label span{color:#ba8f7a}.book-form label small{font-size:9px;color:#abb1a7;letter-spacing:.7px;font-weight:600}.book-form input,.book-form select,.book-form textarea,.notes-panel textarea{width:100%;border:1px solid #e0e6dd;border-radius:5px;background:#fcfdfa;padding:11px 12px;outline:none;color:#364437;resize:vertical}.book-form input:focus,.book-form select:focus,.book-form textarea:focus,.notes-panel textarea:focus{border-color:#91aa8f;box-shadow:0 0 0 3px #eaf1e8}.book-form input::placeholder,.book-form textarea::placeholder,.notes-panel textarea::placeholder{color:#b6bdb3}.form-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:5px}.form-error{color:#a54e44;font-size:12px;line-height:1.5}.detail-shell{max-width:1050px;margin:auto;padding:38px 20px 0}.back-link{display:inline-flex;align-items:center;gap:9px;color:#849384;font-size:12px;font-weight:700;margin-bottom:43px}.back-link:hover{color:#405e45}.detail-grid{display:grid;grid-template-columns:280px 1fr;gap:65px}.detail-cover{background:#ebf0e7;border-radius:6px;padding:30px;display:flex;align-items:flex-start;justify-content:center;height:370px}.cover-large{width:210px;height:310px;box-shadow:8px 10px 20px #53645033}.cover-large .cover-fallback{font-size:27px;padding:20px;gap:20px}.cover-large .cover-fallback small{font-size:11px}.detail-content>.eyebrow{margin:6px 0 28px}.detail-content h1{font-size:45px;margin:15px 0 8px}.detail-author{font-size:14px;color:#979e93;margin:0}.detail-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:27px}.notes-panel{margin-top:40px;padding:25px 0;border-top:1px solid #e3e8df;border-bottom:1px solid #e3e8df}.notes-heading{display:flex;justify-content:space-between;align-items:center}.notes-heading h2{font-size:25px}.edit-button,.remove-button{display:inline-flex;align-items:center;gap:7px;background:none;border:0;color:#789078;font-size:11px;font-weight:700}.notes-text{font-family:var(--serif);font-size:17px;line-height:1.7;color:#687469;white-space:pre-wrap;margin:20px 0 0}.notes-text.muted{font-family:var(--sans);font-size:12px;color:#a1a99e}.notes-panel form{margin-top:20px}.remove-button{color:#a9aaa2;margin-top:23px;padding:0}.remove-button:hover{color:#a65e55}.not-found{max-width:700px;margin:15vh auto;padding:20px}.not-found h1{font-size:45px}.not-found>p:not(.eyebrow){color:#92998f;margin:20px 0 25px}
@media(max-width:900px){.header-inner{gap:35px}.header-note{display:none}.hero{grid-template-columns:1fr 300px}.hero-art{height:220px}.art-books{right:20px}.art-quote{left:22px;width:110px;font-size:16px}.book-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.stats{padding:0 15px}.stat{padding-left:15px;gap:8px}.stat-intro{gap:8px}.stat span{font-size:10px}}
