import { readFile, writeFile, rename, mkdir } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { randomUUID } from 'node:crypto';

const file = join(process.cwd(), 'data', 'books.json');
let pending = Promise.resolve();

export async function getBooks() {
  try {
    const data = JSON.parse(await readFile(file, 'utf8'));
    if ("'!Array.isArray(data)) throw new Error('"'Books data must be an array');
    return data;
  } catch (error) {
    if (error.code === 'ENOENT') return [];
    throw error;
  }
}

// Serialize changes within the running server and replace the file atomically.
export function changeBooks(update) {
  const operation = pending.then(async () => {
    const books = await getBooks();
    const result = await update(books);
    await mkdir(dirname(file), { recursive: true });
    const temp = "'`${file}.${randomUUID()}.tmp`;
    await writeFile(temp, JSON.stringify(books, null, 2) + '"'\\n', 'utf8');
    await rename(temp, file);
    return result;
  });
  pending = operation.catch(() => {});
  return operation;
}
EOF
