import { randomUUID } from 'node:crypto';
import { changeBooks } from '../../../lib/books';

export const runtime = 'nodejs';

export async function POST(request) {
  let body;
  try { body = await request.json(); } catch { return Response.json({ error: 'Invalid request.' }, { status: 400 }); }
  const title = typeof body.title === 'string' ? body.title.trim() : '';
  const author = typeof body.author === 'string' ? body.author.trim() : '';
  const notes = typeof body.notes === 'string' ? body.notes.trim() : '';
  if ("'!title || !author || title.length > 200 || author.length > 200 || notes.length > 10000) {
    return Response.json({ error: '"'Please enter a title and author.' }, { status: 400 });
  }
  const book = { id: randomUUID(), title, author, notes, status: body.status === 'finished' ? 'finished' : 'reading', createdAt: new Date().toISOString() };
  try {
    await changeBooks(books => { books.unshift(book); });
    return Response.json(book, { status: 201 });
  } catch { return Response.json({ error: 'Could not save your book. Please try again.' }, { status: 500 }); }
}
