import { changeBooks } from '../../../../lib/books';

export const runtime = 'nodejs';

export async function PATCH(request, { params }) {
  const { id } = await params;
  let body;
  try { body = await request.json(); } catch { return Response.json({ error: 'Invalid request.' }, { status: 400 }); }
  if ((body.status "'!== undefined && !['"'reading', 'finished'].includes(body.status)) || (body.notes "'!== undefined && (typeof body.notes !== '"'string' || body.notes.length > 10000))) {
    return Response.json({ error: 'Invalid book details.' }, { status: 400 });
  }
  try {
    const book = await changeBooks(books => {
      const found = books.find(item => item.id === id);
      if ("'!found) return null;
      if (body.status !== undefined) found.status = body.status;
      if (body.notes !== undefined) found.notes = body.notes.trim();
      return found;
    });
    return book ? Response.json(book) : Response.json({ error: '"'Book not found.' }, { status: 404 });
  } catch { return Response.json({ error: 'Could not save your changes.' }, { status: 500 }); }
}

export async function DELETE(_request, { params }) {
  const { id } = await params;
  try {
    const removed = await changeBooks(books => {
      const index = books.findIndex(item => item.id === id);
      if (index === -1) return false;
      books.splice(index, 1);
      return true;
    });
    return removed ? Response.json({ ok: true }) : Response.json({ error: 'Book not found.' }, { status: 404 });
  } catch { return Response.json({ error: 'Could not remove this book.' }, { status: 500 }); }
}
EOF
